pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        uint256 capped = bound(amount, 1, 1 ether);

        vm.deal(address(c), 1 ether);

        bool ok;
        vm.prank(caller);
        try c.sendTo(caller, capped) {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = address(this);

        assertTrue(!(ok && caller != owner));
    }
}
